from fractions import Fraction as F
rows=[('A',5,0,0,0,1),('A',6,1,0,1,0),('B',11,0,0,0,1),('B',5,0,1,1,0),('C',6,0,1,0,1),('C',4,1,0,1,1),('D',6,0,0,1,0),('D',8,1,1,0,0)]
tests=['T','U','V','W']; costs=[F(1),F(1),F(17,10),F(21,10)]
loss=[[0,7,10,21],[7,0,22,11],[19,13,0,19],[12,6,13,0]]
def stop(ids):
 w=sum(rows[i][1] for i in ids)
 return min((F(sum(rows[i][1]*loss[a]['ABCD'.index(rows[i][0])] for i in ids),w),'ABCD'[a]) for a in range(4))
def testval(ids,t,remaining):
 w=sum(rows[i][1] for i in ids); val=costs[t]; branches={}
 for bit in [0,1]:
  sub=tuple(i for i in ids if rows[i][t+2]==bit)
  if not sub: branches[str(bit)]='IMPOSSIBLE'; continue
  opts=[stop(sub)]
  if remaining:
   opts += [(testval(sub,s,False)[0],tests[s]) for s in range(4) if s!=t]
  v,a=min(opts); branches[str(bit)]=a
  val+=F(sum(rows[i][1] for i in sub),w)*v
 return val,branches
ids=tuple(range(8))
print('STOP',stop(ids))
for t in range(4):
 v,b=testval(ids,t,True);print(tests[t],float(v),str(v),b)

