from fractions import Fraction as F
# U=0 rows; repeated display is the same event
rows=[('A',5,0,0,1),('A',6,1,1,0),('B',11,0,0,1),('C',4,1,1,1),('D',6,0,1,0)]
loss={'A':[0,7,10,21],'B':[7,0,22,11],'C':[19,13,0,19],'D':[12,6,13,0]}
W=sum(r[1] for r in rows)
def repairs(rs):
 w=sum(r[1] for r in rs)
 return {a:F(sum(r[1]*ls['ABCD'.index(r[0])] for r in rs),w) for a,ls in loss.items()}
print('posterior',{a:float(F(sum(r[1] for r in rows if r[0]==a),W)) for a in 'ABCD'})
print('repairs',{a:float(v) for a,v in repairs(rows).items()})
for name,col,cost in [('T',2,F(7)),('V',3,F(17,10)),('W',4,F(21,10))]:
 val=cost; branch={}
 for b in [0,1]:
  rs=[r for r in rows if r[col]==b]
  if not rs: branch[str(b)]='IMPOSSIBLE';continue
  vals=repairs(rs); a=min(vals,key=vals.get);branch[str(b)]=a
  val+=F(sum(r[1] for r in rs),W)*vals[a]
 print(name,float(val),branch)

